begin;
select no_plan();
\ir ../support/academic-fixture.psql
select has_function('public','get_dashboard',array['jsonb'],'role-specific dashboard exists');
select has_function('public','get_my_evaluations',array['jsonb','text','jsonb'],'scoped evaluations exist');
select has_function('public','get_leadership_aggregates',array['jsonb'],'safe aggregates exist');
select has_function('public','get_scoped_audit',array['jsonb','jsonb'],'safe audit exists');
insert into auth.users(id,email,aud,role) select pg_temp.fixture(who),who||'@example.invalid','authenticated','authenticated' from unnest(array['cam','manager','district-manager','leader','admin'])who;
insert into public.contas_demo(ator_id,rotulo) select pg_temp.fixture(who),who from unnest(array['actor','reviewer','cam','manager','district-manager','leader','admin'])who;
insert into public.competencias(id,codigo,referencia,estado,modelo) values(pg_temp.fixture('read-cycle'),'READ-2026-10','2026-10-01','aberta',2);
insert into public.escopos(id,codigo,tipo) select pg_temp.fixture('read-scope-'||n),case n when 1 then 'NORTE' when 2 then 'ALFA' when 3 then 'BETA' when 4 then 'GAMA' when 5 then 'SUL' else 'DELTA' end,case when n in (1,5) then 'distrito' else 'unidade' end from generate_series(1,6)n;
insert into public.territorios_competencia(competencia_id,unidade_id,distrito_id) select pg_temp.fixture('read-cycle'),pg_temp.fixture('read-scope-'||n),pg_temp.fixture('read-scope-'||case when n=6 then 5 else 1 end) from unnest(array[2,3,4,6])n;
insert into public.posicoes_esperadas(id,competencia_id,indicador_id,alvo_id,regra_id,informante_id,revisor_id) select pg_temp.fixture('read-pos-'||n),pg_temp.fixture('read-cycle'),'c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('read-scope-'||n),'c0de0000-0000-4000-8000-000000000004',pg_temp.fixture('actor'),pg_temp.fixture('reviewer') from generate_series(1,6)n;
insert into public.vinculos(actor_id,papel,escopo_id,indicador_id,vigencia_inicio) select pg_temp.fixture(who),role,pg_temp.fixture('read-scope-'||n),'c0de0000-0000-4000-8000-000000000002',current_date-1 from generate_series(1,6)n cross join(values('actor','area_tecnica'),('reviewer','revisor_tecnico'),('cam','cam'))v(who,role);
insert into public.vinculos(actor_id,papel,escopo_id,indicador_id,vigencia_inicio) select pg_temp.fixture(who),role,pg_temp.fixture('read-scope-'||n),'c0de0000-0000-4000-8000-000000000002',current_date-1 from(values('manager','gestor_unidade',2),('district-manager','gestor_distrital',1),('leader','lideranca',1),('admin','administrador',1))v(who,role,n);
create function pg_temp.read_ctx(who text,n integer default 1) returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',pg_temp.fixture('read-cycle'),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture(who) and escopo_id=pg_temp.fixture('read-scope-'||case when who='manager' then 2 else n end);$$;
create function pg_temp.prepare_read_cycle() returns void language plpgsql as $$declare n integer;r jsonb;begin
 for n in 1..6 loop
  perform pg_temp.login_as('actor');r:=public.save_position_draft(pg_temp.read_ctx('actor',n),pg_temp.fixture('read-pos-'||n),1,jsonb_build_object('estadoDado',case when n=4 then 'indisponivel' else 'valor' end,'valor',case when n=4 then null when n=3 then '12' when n in (1,5) then '100' else '10' end,'fonte','synthetic private origin','periodoFonte','2026-10-01','motivo',case when n=4 then 'private unavailable reason' else '' end),gen_random_uuid());
  r:=public.submit_position(pg_temp.read_ctx('actor',n),pg_temp.fixture('read-pos-'||n),(r->>'version')::integer,gen_random_uuid());
  perform pg_temp.login_as('reviewer');r:=public.start_position_review(pg_temp.read_ctx('reviewer',n),pg_temp.fixture('read-pos-'||n),(r->>'version')::integer,gen_random_uuid());
  r:=public.review_position(pg_temp.read_ctx('reviewer',n),pg_temp.fixture('read-pos-'||n),(r->>'version')::integer,'accept','private independent review reason',gen_random_uuid());
  if n=4 then perform pg_temp.login_as('cam');perform public.decide_unavailability(pg_temp.read_ctx('cam',n),pg_temp.fixture('read-pos-'||n),(r->>'version')::integer,'DEMO-UNAVAILABLE-READ','private CAM reason',gen_random_uuid());end if;
 end loop;
end;$$;
select pg_temp.login_as('manager');set local role authenticated;
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->>'total','0','manager does not receive draft/missing work');
select throws_ok($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'territory','{}')$$,'42501','access_denied','unit manager cannot enlarge view');
select throws_ok($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{"page":0}')$$,'22023','invalid_input','page zero rejected');
select throws_ok($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{"pageSize":101}')$$,'22023','invalid_input','page size 101 rejected');
select lives_ok(format($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'own',%L)$$,jsonb_build_object('search',repeat('a',100))::text),'read-model search of 100 characters accepted');
select throws_ok(format($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'own',%L)$$,jsonb_build_object('search',repeat('a',101))::text),'22023','invalid_input','read-model search over 100 characters rejected');
select lives_ok('select pg_temp.prepare_read_cycle()','prepare only via actual submission and independent acceptance');
select pg_temp.login_as('manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'resultValue','8','ALFA own result only');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{"search":"BETA"}')->>'total','0','search never enlarges scope');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'publication','preliminar','validated result is preliminary');
select ok(not(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0 ?| array['actorId','authorId','reason','source','decisions']),'manager response sanitized on server');
select is(public.get_scoped_audit(pg_temp.read_ctx('manager'),'{}')->'items'->0->'reason','null'::jsonb,'manager history excludes internal reason');
select is(public.get_scoped_audit(pg_temp.read_ctx('manager'),'{"search":"ALFA"}')->>'total','1','manager audit search finds its authorized target');
select is(public.get_scoped_audit(pg_temp.read_ctx('manager'),'{"search":"BETA"}')->>'total','0','target search never widens manager scope');
select pg_temp.login_as('reviewer');
select is(public.get_scoped_audit(pg_temp.read_ctx('reviewer',2),'{"search":"ALFA"}')->>'total','4','operational audit search finds authorized target');
select is(public.get_scoped_audit(pg_temp.read_ctx('reviewer',2),'{"search":"BETA"}')->>'total','0','operational target search cannot read another assignment');
savepoint temporary_rectification;
select pg_temp.login_as('cam');
select public.authorize_position_correction(pg_temp.read_ctx('cam',2),pg_temp.fixture('read-pos-2'),5,'Private correction instruction',gen_random_uuid());
select pg_temp.login_as('manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->>'total','0','rectification withdraws the previously accepted result, not a stale preliminary value');
select is(public.get_scoped_audit(pg_temp.read_ctx('manager'),'{}')->>'total','0','internal correction does not remain an eligible evaluation history');
rollback to savepoint temporary_rectification;
savepoint temporary_non_applicable;
reset role;
-- Adversarial applicability fixture only; acceptance above remains real.
update public.posicoes_esperadas set aplicavel=false where id=pg_temp.fixture('read-pos-2');
select pg_temp.login_as('leader');set local role authenticated;
select is(public.get_dashboard(pg_temp.read_ctx('leader'))->>'expected','3','non-applicable remains in the authorized denominator');
select is(public.get_dashboard(pg_temp.read_ctx('leader'))->>'received','2','non-applicable is not a received applicable result');
select is(public.get_dashboard(pg_temp.read_ctx('leader'))->>'reviewed','2','non-applicable is not a technically reviewed applicable result');
select pg_temp.login_as('manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'estadoDado','nao_aplicavel','non-applicability has an explicit evaluation state');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->'resultValue','null'::jsonb,'non-applicable is not zero or a previous numeric result');
rollback to savepoint temporary_non_applicable;
select pg_temp.login_as('district-manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('district-manager'),'own','{}')->'items'->0->>'resultValue','80','district own result is not unit sum');
select is(public.get_my_evaluations(pg_temp.read_ctx('district-manager'),'territory','{}')->>'total','3','district territory includes only its three units');
select is(public.get_my_evaluations(pg_temp.read_ctx('district-manager'),'territory','{"pageSize":1}')->'items'->0->>'escopoCodigo','ALFA','stable first page');
select is(public.get_my_evaluations(pg_temp.read_ctx('district-manager'),'territory','{"pageSize":1,"page":2}')->'items'->0->>'escopoCodigo','BETA','stable second page');
select pg_temp.login_as('leader');
select is(public.get_dashboard(pg_temp.read_ctx('leader'))->>'expected','3','leadership denominator excludes personal district evaluation');
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader')),'[]'::jsonb,'no unpublished numerical aggregate');
select throws_ok($$select public.get_scoped_audit(pg_temp.read_ctx('leader'),'{}')$$,'42501','access_denied','leadership has no individual audit');
select pg_temp.login_as('cam');
select is(public.get_dashboard(pg_temp.read_ctx('cam'))->>'expected','6','CAM denominator follows explicit operational union');
select is(public.get_dashboard(pg_temp.read_ctx('cam'))->'cards'->0->>'count','6','all card reconciles');
select is(public.get_dashboard(pg_temp.read_ctx('cam'))->'cards'->6->>'count','6','validated card reconciles exact filter');
select is(public.get_operational_positions(pg_temp.read_ctx('cam'),public.get_dashboard(pg_temp.read_ctx('cam'))->'cards'->6->'filter')->>'total','6','card drilldown list uses same scope and state');
select public.transition_cycle(pg_temp.read_ctx('cam'),(public.get_cycle_checklist(pg_temp.read_ctx('cam'))->>'version')::integer,'consolidate','','',gen_random_uuid());
select public.transition_cycle(pg_temp.read_ctx('cam'),(public.get_cycle_checklist(pg_temp.read_ctx('cam'))->>'version')::integer,'close','','DEMO-DECISAO-READ',gen_random_uuid());
select public.publish_cycle_demo(pg_temp.read_ctx('cam'),(public.get_cycle_checklist(pg_temp.read_ctx('cam'))->>'snapshotId')::uuid,'DEMO-PUBLICACAO-READ',gen_random_uuid());
select pg_temp.login_as('leader');
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0->>'resultSum','17.6','8 plus 9.6 is non-financial unit sum, excludes district 80');
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0->>'publishedUnits','3','unavailable unit remains published denominator');
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0->>'calculableUnits','2','unavailable is not zero or calculable');
select ok(not(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0 ?| array['actorId','positionId','id','inputValue','escopoId']),'aggregate has no individual identifiers or input');
reset role;
update public.escopos set distrito_id=pg_temp.fixture('read-scope-5') where id=pg_temp.fixture('read-scope-2');
-- Adversarial transaction-only administrative events; no admin workflow is asserted implemented.
insert into public.eventos_auditoria(actor_id,acao,recurso_tipo,recurso_id,detalhes) values(pg_temp.fixture('admin'),'vinculo_demo_alterado','vinculo',pg_temp.fixture('read-scope-2'),'{"version":2,"reason":"secret","inputValue":"999","actorId":"secret"}');
select pg_temp.login_as('leader');set local role authenticated;
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0->>'resultSum','17.6','current catalogue cannot rewrite frozen aggregate');
select pg_temp.login_as('manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'publication','publicada_demo','manager now reads published snapshot');
select pg_temp.login_as('admin');
select is(public.get_scoped_audit(pg_temp.read_ctx('admin'),'{}')->>'total','1','admin only receives administrative action whitelist');
select is(public.get_scoped_audit(pg_temp.read_ctx('admin'),'{}')->'items'->0->'reason','null'::jsonb,'admin cannot read free business reason');
select is(public.get_scoped_audit(pg_temp.read_ctx('admin'),'{"search":"ALFA"}')->>'total','0','administrative search never joins evaluation targets');
select ok(not(public.get_scoped_audit(pg_temp.read_ctx('admin'),'{}')->'items'->0 ?| array['detalhes','inputValue','actorId','resultValue']),'admin audit strips business payload');
select throws_ok($$select public.get_dashboard(pg_temp.read_ctx('admin'))$$,'42501','access_denied','admin not operational dashboard');
select throws_ok($$select public.get_my_evaluations(pg_temp.read_ctx('admin'),'own','{}')$$,'42501','access_denied','admin not individual evaluations');
select pg_temp.login_as('reviewer');
select is(public.get_scoped_audit(pg_temp.read_ctx('reviewer',2),'{}')->>'total','4','reviewer never receives administrative history');
select is((select count(*)::integer from public.entradas where posicao_id=pg_temp.fixture('read-pos-3')),0,'direct business table access remains denied by RLS');
select throws_ok($$select * from public.itens_fechamento$$,'42501',null,'snapshot table direct reads denied');
reset role;
select ok(not has_function_privilege('anon','public.get_dashboard(jsonb)','execute'),'anonymous read denied');
select ok(not has_function_privilege('authenticated','private.evaluation_rows(jsonb,text)','execute'),'private evaluation helper denied');
-- Transaction-only future metadata. T13 commands are not being claimed here;
-- values and technical acceptance still go through the real command APIs.
insert into public.competencias(id,codigo,referencia,estado,modelo) values(pg_temp.fixture('read-later-cycle'),'READ-2026-11','2026-11-01','aberta',2);
insert into public.regras(id,indicador_id,versao,fator,vigencia_inicio) values(pg_temp.fixture('read-later-rule'),'c0de0000-0000-4000-8000-000000000002',2,0.9,'2026-11-01');
insert into public.ativacoes_regra(indicador_id,regra_id,primeiro_mes,referencia_demo) values('c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('read-later-rule'),'2026-11-01','DEMO-REGRA-READ-NOV');
insert into public.territorios_competencia(competencia_id,unidade_id,distrito_id) values(pg_temp.fixture('read-later-cycle'),pg_temp.fixture('read-scope-2'),pg_temp.fixture('read-scope-5'));
insert into public.posicoes_esperadas(id,competencia_id,indicador_id,alvo_id,regra_id,informante_id,revisor_id) values(pg_temp.fixture('read-later-pos'),pg_temp.fixture('read-later-cycle'),'c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('read-scope-2'),pg_temp.fixture('read-later-rule'),pg_temp.fixture('actor'),pg_temp.fixture('reviewer'));
create function pg_temp.later_ctx(who text) returns jsonb language sql security definer as $$select jsonb_set(pg_temp.read_ctx(who,2),'{competenciaId}',to_jsonb(pg_temp.fixture('read-later-cycle')));$$;
create function pg_temp.prepare_later_evaluation() returns void language plpgsql as $$declare r jsonb;begin
 perform pg_temp.login_as('actor');r:=public.save_position_draft(pg_temp.later_ctx('actor'),pg_temp.fixture('read-later-pos'),1,'{"estadoDado":"valor","valor":"10","fonte":"Synthetic November source","periodoFonte":"2026-11-01","motivo":""}',gen_random_uuid());
 r:=public.submit_position(pg_temp.later_ctx('actor'),pg_temp.fixture('read-later-pos'),(r->>'version')::integer,gen_random_uuid());
 perform pg_temp.login_as('reviewer');r:=public.start_position_review(pg_temp.later_ctx('reviewer'),pg_temp.fixture('read-later-pos'),(r->>'version')::integer,gen_random_uuid());
 perform public.review_position(pg_temp.later_ctx('reviewer'),pg_temp.fixture('read-later-pos'),(r->>'version')::integer,'accept','Independent November evidence',gen_random_uuid());
end;$$;
set local role authenticated;
select lives_ok('select pg_temp.prepare_later_evaluation()','later version has real independently accepted result');
select pg_temp.login_as('manager');
select is(public.get_my_evaluations(pg_temp.later_ctx('manager'),'own','{}')->'items'->0->>'ruleVersion','2','new month exposes its own pinned rule version');
select is(public.get_my_evaluations(pg_temp.later_ctx('manager'),'own','{}')->'items'->0->>'factor','0.9','new month uses new factor');
select is(public.get_my_evaluations(pg_temp.later_ctx('manager'),'own','{}')->'items'->0->>'resultValue','9','new month result is separate, not a retroactive recalculation');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'ruleVersion','1','published past keeps rule v1 after future v2 exists');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'factor','0.8','published past keeps original factor');
select is(public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')->'items'->0->>'resultValue','8','published past is not recomputed with latest factor');
select pg_temp.login_as('district-manager');
select is(public.get_my_evaluations(pg_temp.read_ctx('district-manager'),'territory','{"search":"ALFA"}')->>'total','1','historical district retains ALFA despite new month assigning ALFA to SUL');
select pg_temp.login_as('leader');
select is(public.get_leadership_aggregates(pg_temp.read_ctx('leader'))->0->>'resultSum','17.6','future rule and territory do not alter past published aggregate');
reset role;
-- Revocation is current authority, including reads of an already published snapshot.
update public.vinculos set ativo=false where actor_id in (pg_temp.fixture('manager'),pg_temp.fixture('leader'),pg_temp.fixture('admin'),pg_temp.fixture('actor')) and indicador_id is not null;
select pg_temp.login_as('manager');set local role authenticated;
select throws_ok($$select public.get_my_evaluations(pg_temp.read_ctx('manager'),'own','{}')$$,'42501','access_denied','revoked manager cannot recover published values');
select throws_ok($$select public.get_scoped_audit(pg_temp.read_ctx('manager'),'{}')$$,'42501','access_denied','revoked manager cannot recover history');
select pg_temp.login_as('leader');
select throws_ok($$select public.get_leadership_aggregates(pg_temp.read_ctx('leader'))$$,'42501','access_denied','revoked leadership cannot recover aggregates');
select throws_ok($$select public.get_dashboard(pg_temp.read_ctx('leader'))$$,'42501','access_denied','revoked leadership cannot recover aggregate counters');
select pg_temp.login_as('admin');
select throws_ok($$select public.get_scoped_audit(pg_temp.read_ctx('admin'),'{}')$$,'42501','access_denied','revoked administrator cannot recover administrative metadata');
select pg_temp.login_as('actor');
select throws_ok($$select public.get_dashboard(pg_temp.read_ctx('actor',2))$$,'42501','access_denied','revoked technical link cannot recover counters');
reset role;
select * from finish();rollback;
